from typing import List

def redistributeMegaseeds(seeds: List[int]) -> int:
    S = sum(seeds)
    if S < 2:
        return -1
    primes, x, p = [], S, 2
    while p * p <= x:
        if x % p == 0:
            primes.append(p)
            while x % p == 0:
                x //= p
        p += 1
    if x > 1:
        primes.append(x)
    best = None
    for p in primes:
        ops, pref = 0, 0
        for v in seeds:
            pref += v
            r = pref % p
            ops += min(r, p - r)
        best = ops if best is None else min(best, ops)
    return best

if __name__ == "__main__":
    import sys
    data = list(map(int, sys.stdin.read().split()))
    print(redistributeMegaseeds(data[1:1 + data[0]]))
